import java.util.*;
import java.io.*;

public class Main {
    static char[][] s1 = new char[15][15];
    static char[][] s2 = new char[15][15];
    static int[][][] idx = new int[65][15][15];
    static int[][] dp = new int[15][15];
    static int[] dirX = {-1, 1, 0, 0};
    static int[] dirY = {0, 0, -1, 1};
    static int id = 1;
    static final long INF = Long.MAX_VALUE / 2;

    static class Edge {
        int u, v;
        long cap;
        long flow;

        public Edge(int u, int v, long cap) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = 0;
        }
    }

    static class Dinic {
        int N;
        List<Edge> E = new ArrayList<>();
        List<List<Integer>> g;
        int[] d;
        int[] pt;

        public Dinic(int N) {
            this.N = N;
            g = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                g.add(new ArrayList<>());
            }
            d = new int[N];
            pt = new int[N];
        }

        void addEdge(int u, int v, long cap) {
            if (u != v) {
                E.add(new Edge(u, v, cap));
                g.get(u).add(E.size() - 1);
                E.add(new Edge(v, u, 0));
                g.get(v).add(E.size() - 1);
            }
        }

        boolean BFS(int S, int T) {
            Arrays.fill(d, N + 1);
            Queue<Integer> q = new LinkedList<>();
            q.offer(S);
            d[S] = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == T) break;
                for (int k : g.get(u)) {
                    Edge e = E.get(k);
                    if (e.flow < e.cap && d[e.v] > d[e.u] + 1) {
                        d[e.v] = d[e.u] + 1;
                        q.offer(e.v);
                    }
                }
            }
            return d[T] != N + 1;
        }

        long DFS(int u, int T, long flow) {
            if (u == T || flow == 0) return flow;
            for (; pt[u] < g.get(u).size(); pt[u]++) {
                int k = g.get(u).get(pt[u]);
                Edge e = E.get(k);
                Edge oe = E.get(k ^ 1);
                if (d[e.v] == d[e.u] + 1) {
                    long amt = e.cap - e.flow;
                    if (flow != -1 && amt > flow) amt = flow;
                    long pushed = DFS(e.v, T, amt);
                    if (pushed > 0) {
                        e.flow += pushed;
                        oe.flow -= pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int S, int T) {
            long total = 0;
            while (BFS(S, T)) {
                Arrays.fill(pt, 0);
                long flow;
                while ((flow = DFS(S, T, -1)) > 0) {
                    total += flow;
                }
            }
            return total;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int t = Integer.parseInt(line[1]);
        for (int i = 1; i <= n; i++) {
            s1[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i <= t + 1; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= n; k++) {
                    idx[i][j][k] = id++;
                }
            }
        }
        id++;
        for (int i = 1; i <= n; i++) {
            s2[i] = br.readLine().toCharArray();
        }

        int[][] dpArr = new int[n + 1][n + 1];
        for (int[] row : dpArr)
            Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1[i][j - 1] == 'Z') {
                    q.offer(new int[]{i, j});
                    dpArr[i][j] = 0;
                }
            }
        }
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int uy = cell[0], ux = cell[1];
            for (int i = 0; i < 4; i++) {
                int vy = uy + dirX[i], vx = ux + dirY[i];
                if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && s1[vy][vx - 1] != 'Y' && dpArr[vy][vx] == -1) {
                    dpArr[vy][vx] = dpArr[uy][ux] + 1;
                    q.offer(new int[]{vy, vx});
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (dpArr[i][j] == -1) dpArr[i][j] = 1000000000;
                if (dpArr[i][j] > t) dpArr[i][j] = 1000000000;
            }
        }

        int source = 0;
        int sink = id - 1;

        Dinic dinic = new Dinic(id);

        // from source to first layer
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1[i - 1][j - 1] >= '1' && s1[i - 1][j - 1] <= '9') {
                    int capacity = s1[i - 1][j - 1] - '0';
                    dinic.addEdge(source, idx[0][i][j], capacity);
                }
            }
        }

        // add edges between grid cells
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1[i - 1][j - 1] == 'Y' || s1[i - 1][j - 1] == 'Z') continue;
                for (int k = 0; k < 4; k++) {
                    int vy = i + dirX[k], vx = j + dirY[k];
                    if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && s1[vy - 1][vx - 1] != 'Y' && s1[vy - 1][vx - 1] != 'Z') {
                        for (int x = 0; x < t; x++) {
                            if (dpArr[vy][vx] >= x + 1 && dpArr[i][j] > x) {
                                dinic.addEdge(idx[x][i][j], idx[x +1][vy][vx], 1000);
                            }
                        }
                    }
                }
            }
        }

        // add edges from grid cells to sink based on s2
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1[i - 1][j - 1] == 'Y' || s1[i - 1][j - 1] == 'Z') continue;
                if (s2[i - 1][j - 1] >= '1' && s2[i - 1][j - 1] <= '9') {
                    int cap = s2[i - 1][j - 1] - '0';
                    for (int x=0; x<=t; x++) {
                        dinic.addEdge(idx[x][i][j], idx[t+1][i][j], cap);
                    }
                }
            }
        }

        // edges from sink nodes to sink
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (s1[i - 1][j - 1] == 'Y' || s1[i - 1][j - 1] == 'Z') continue;
                if (s2[i - 1][j - 1] >= '1' && s2[i - 1][j - 1] <= '9') {
                    int cap = s2[i - 1][j - 1] - '0';
                    dinic.addEdge(idx[t+1][i][j], sink, cap);
                }
            }
        }

        System.out.println(dinic.maxFlow(source, sink));
    }
}
